<?php
declare(strict_types=1);

require dirname(__DIR__) . '/auth_store.php';
header('Content-Type: application/json; charset=UTF-8');
header('Cache-Control: no-store, no-cache, must-revalidate');

const TT_PIT_FILE = TT_DATA_DIR . '/accounts.json';
const TT_PIT_MASTER = __DIR__ . '/../accounts/accounting_master_v1.json';

function pit_out(array $d,int $s=200):never{http_response_code($s);echo json_encode($d,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);exit;}
function pit_can_write(array $u):bool{if(($u['role']??'')==='Super Admin')return true;$p=$u['permissions']['Accounts']??null;if($p==='all')return true;if(!is_array($p))return false;if(in_array('Create',$p,true)||in_array('Edit',$p,true)||in_array('Approve',$p,true))return true;foreach($p as $a)if(is_array($a)&&(in_array('Create',$a,true)||in_array('Edit',$a,true)||in_array('Approve',$a,true)))return true;return false;}
function pit_def():array{return ['revision'=>0,'journals'=>[],'productionCostRuns'=>[],'productionInventoryTransfers'=>[],'salaryMasters'=>[],'rentMasters'=>[]];}
function pit_read():array{tt_ensure_data_dir();if(!is_file(TT_PIT_FILE))return pit_def();$h=fopen(TT_PIT_FILE,'r');if($h===false||!flock($h,LOCK_SH))throw new RuntimeException('Accounts storage unavailable.');try{$raw=stream_get_contents($h);}finally{flock($h,LOCK_UN);fclose($h);}$v=$raw?json_decode($raw,true):null;return is_array($v)?array_replace_recursive(pit_def(),$v):pit_def();}
function pit_entity(string $v):string{$v=strtoupper(trim($v));if(!in_array($v,['TTI','BRM'],true))pit_out(['ok'=>false,'error'=>'Production stock value is available for TTI / BRM.'],422);return $v;}
function pit_names():array{$raw=is_file(TT_PIT_MASTER)?file_get_contents(TT_PIT_MASTER):false;$m=$raw?json_decode($raw,true):null;if(!is_array($m))throw new RuntimeException('Accounting master unavailable.');$o=[];foreach((array)($m['chart']??[]) as $a)if(is_array($a)&&isset($a['code']))$o[(string)$a['code']]=(string)($a['name']??$a['code']);return $o;}
function pit_line(string $a,float $dr,float $cr,array $names,array $extra=[]):array{if(!isset($names[$a]))pit_out(['ok'=>false,'error'=>'Approved account '.$a.' is unavailable.'],422);return array_merge(['account'=>$a,'accountName'=>$names[$a],'debit'=>round($dr,2),'credit'=>round($cr,2)],$extra);}
function pit_next(array $items,string $p):string{$n=count($items)+1;do{$id=$p.'-'.gmdate('Y').'-'.str_pad((string)$n,6,'0',STR_PAD_LEFT);$n++;}while(isset($items[$id]));return $id;}
function pit_active(array $m,string $month):bool{if(($m['status']??'Active')!=='Active')return false;$from=(string)($m['effectiveFrom']??'');$to=(string)($m['effectiveTo']??'');$start=$month.'-01';$end=(new DateTimeImmutable($start))->modify('last day of this month')->format('Y-m-d');return ($from===''||$from<=$end)&&($to===''||$to>=$start);}
function pit_fixed_needed(array $s,string $entity,string $month):bool{foreach((array)$s['salaryMasters'] as $m){if(!is_array($m)||($m['entity']??'')!==$entity||!pit_active($m,$month))continue;if(($m['category']??'')==='MILL_STAFF'&&!empty($m['productionCostEligible'])&&(($m['accountingTreatment']??'STAFF_COST')==='STAFF_COST'))return true;}foreach((array)$s['rentMasters'] as $m){if(is_array($m)&&($m['entity']??'')===$entity&&pit_active($m,$month)&&!empty($m['productionCostEligible']))return true;}return false;}
function pit_preview(array $s,array $run):array{$entity=(string)($run['entity']??'');$date=(string)($run['date']??'');$month=substr($date,0,7);$calc=is_array($run['calculation']??null)?$run['calculation']:[];$raw=round((float)($calc['rawCost']??0),2);$conversion=round((float)($calc['conversionCost']??0),2);$by=round((float)($calc['byProductValue']??0),2);$readyKg=(float)($calc['readyKg']??0);$fixedNeeded=pit_fixed_needed($s,$entity,$month);$fixedSalary=0.0;$fixedRent=0.0;$wait='';if($raw<=0||$readyKg<=0)$wait='Waiting — approved production cost is incomplete';elseif($fixedNeeded&&empty($run['fixedOverheadAppliedAt']))$wait='Waiting — apply Mill Salary / Rent';else{$f=is_array($run['fixedOverhead']??null)?$run['fixedOverhead']:[];$monthReady=(float)($f['readyRiceKg']??0);if($fixedNeeded&&$monthReady<=0)$wait='Waiting — monthly Ready Rice quantity is missing';elseif($monthReady>0){$ratio=min(1,max(0,$readyKg/$monthReady));$fixedSalary=round((float)($f['millSalary']??0)*$ratio,2);$fixedRent=round((float)($f['millRent']??0)*$ratio,2);}}$fixed=round($fixedSalary+$fixedRent,2);$ready=round($raw+$conversion+$fixed-$by,2);if($wait===''&&$ready<=0)$wait='Waiting — calculated Ready Rice value is invalid';$gid=(string)($run['id']??'');$posted=is_array($s['productionInventoryTransfers'][$gid]??null)?$s['productionInventoryTransfers'][$gid]:null;return ['groupId'=>$gid,'entity'=>$entity,'date'=>$date,'month'=>$month,'variety'=>(string)($run['variety']??''),'readyKg'=>round($readyKg,3),'rawValue'=>$raw,'conversionValue'=>$conversion,'fixedSalaryValue'=>$fixedSalary,'fixedRentValue'=>$fixedRent,'fixedValue'=>$fixed,'byProductValue'=>$by,'readyRiceValue'=>$ready,'readyRiceCostPerKg'=>$readyKg>0?round($ready/$readyKg,6):0,'fixedNeeded'=>$fixedNeeded,'readyToPost'=>$wait===''&&!$posted,'status'=>$posted?'Posted':($wait?:'Ready to Post'),'journalId'=>$posted['journalId']??'','postedAt'=>$posted['postedAt']??''];}
function pit_payload(array $s,string $entity):array{$rows=[];foreach((array)$s['productionCostRuns'] as $run){if(!is_array($run)||($run['entity']??'')!==$entity)continue;$rows[]=pit_preview($s,$run);}usort($rows,static fn($a,$b)=>strcmp((string)$b['date'],(string)$a['date']));return ['ok'=>true,'entity'=>$entity,'rows'=>$rows,'serverNow'=>gmdate('c')];}

try{$u=tt_require_login();if(!tt_user_can_open_module($u,'Accounts'))pit_out(['ok'=>false,'error'=>'Accounts permission required.'],403);$entity=pit_entity((string)($_GET['entity']??'TTI'));if($_SERVER['REQUEST_METHOD']==='GET')pit_out(pit_payload(pit_read(),$entity));if($_SERVER['REQUEST_METHOD']!=='POST')pit_out(['ok'=>false,'error'=>'Method not allowed.'],405);if(!pit_can_write($u))pit_out(['ok'=>false,'error'=>'Accounts approval permission required.'],403);$b=json_decode(file_get_contents('php://input')?:'{}',true);if(!is_array($b)||!tt_verify_csrf((string)($b['csrf']??'')))pit_out(['ok'=>false,'error'=>'Your session expired. Refresh and try again.'],419);if(($b['action']??'')!=='post_transfer')pit_out(['ok'=>false,'error'=>'Unknown production stock action.'],422);$groupId=trim((string)($b['groupId']??''));if($groupId==='')pit_out(['ok'=>false,'error'=>'Select a production cost run.'],422);tt_ensure_data_dir();$h=fopen(TT_PIT_FILE,'c+');if($h===false||!flock($h,LOCK_EX))throw new RuntimeException('Accounts storage unavailable.');try{rewind($h);$raw=stream_get_contents($h);$s=$raw?json_decode($raw,true):null;if(!is_array($s))$s=pit_def();$s=array_replace_recursive(pit_def(),$s);$run=$s['productionCostRuns'][$groupId]??null;if(!is_array($run)||($run['entity']??'')!==$entity)pit_out(['ok'=>false,'error'=>'Approved production cost was not found.'],404);if(isset($s['productionInventoryTransfers'][$groupId]))pit_out(['ok'=>false,'error'=>'This production stock value has already been posted.','existing'=>$s['productionInventoryTransfers'][$groupId]],409);$p=pit_preview($s,$run);if(empty($p['readyToPost']))pit_out(['ok'=>false,'error'=>(string)$p['status']],422);$names=pit_names();$meta=['groupId'=>$groupId,'variety'=>$p['variety'],'readyKg'=>$p['readyKg'],'rawValue'=>$p['rawValue'],'conversionValue'=>$p['conversionValue'],'fixedSalaryValue'=>$p['fixedSalaryValue'],'fixedRentValue'=>$p['fixedRentValue'],'byProductValue'=>$p['byProductValue'],'readyRiceValue'=>$p['readyRiceValue'],'quantityRule'=>'Physical quantity remains controlled by Mill production. Accounts posts value only.'];$lines=[pit_line('1320',$p['readyRiceValue'],0,$names,$meta)];if($p['byProductValue']>0)$lines[]=pit_line('1330',$p['byProductValue'],0,$names,$meta);$lines[]=pit_line('1310',0,$p['rawValue'],$names,$meta);if($p['conversionValue']>0)$lines[]=pit_line('5200',0,$p['conversionValue'],$names,$meta+['capitalizedProductionCost'=>true]);if($p['fixedSalaryValue']>0)$lines[]=pit_line('6200',0,$p['fixedSalaryValue'],$names,$meta+['capitalizedMillSalary'=>true]);if($p['fixedRentValue']>0)$lines[]=pit_line('6300',0,$p['fixedRentValue'],$names,$meta+['capitalizedMillRent'=>true]);$dr=round(array_sum(array_map(static fn($l)=>(float)$l['debit'],$lines)),2);$cr=round(array_sum(array_map(static fn($l)=>(float)$l['credit'],$lines)),2);if(abs($dr-$cr)>.005)throw new RuntimeException('Production stock journal did not balance.');$jid=pit_next((array)$s['journals'],'AUTO');$s['journals'][$jid]=['id'=>$jid,'entity'=>$entity,'date'=>$p['date'],'sourceType'=>'PRODUCTION_INVENTORY_TRANSFER','reference'=>'PROD-STOCK|'.$groupId,'narration'=>'Production stock value — '.$p['variety'].' — '.$p['date'],'lines'=>$lines,'totalDebit'=>$dr,'totalCredit'=>$cr,'status'=>'Posted','meta'=>$meta,'createdAt'=>gmdate('c'),'createdBy'=>(string)($u['full_name']??$u['username']??'Accounts'),'userId'=>(int)($u['id']??0),'reversalOf'=>null];$s['productionInventoryTransfers'][$groupId]=['id'=>$groupId,'entity'=>$entity,'date'=>$p['date'],'variety'=>$p['variety'],'journalId'=>$jid,'rawValue'=>$p['rawValue'],'conversionValue'=>$p['conversionValue'],'fixedSalaryValue'=>$p['fixedSalaryValue'],'fixedRentValue'=>$p['fixedRentValue'],'byProductValue'=>$p['byProductValue'],'readyRiceValue'=>$p['readyRiceValue'],'readyKg'=>$p['readyKg'],'postedAt'=>gmdate('c'),'postedBy'=>(string)($u['full_name']??$u['username']??'Accounts')];$s['productionCostRuns'][$groupId]['inventoryTransferJournalId']=$jid;$s['productionCo